#!/bin/bash
# Generated by OrchestKit Claude Plugin
# Created: 2026-07-28
#
# `--changed` fan-out must PROPAGATE exit 2, never flatten it to 1.
# Reference: #3032 (which fixed the single-skill half of this)
#
# Self-contained on purpose: does NOT source the harness and NEVER spawns
# `claude -p`, so it runs in milliseconds and triggers no 1Password prompts.

set -euo pipefail

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
PROJECT_ROOT="$(cd "$SCRIPT_DIR/../.." && pwd)"
RUNNER="$PROJECT_ROOT/tests/evals/scripts/run-skill-eval.sh"
WORKFLOW="$PROJECT_ROOT/.github/workflows/skill-eval.yml"

# Why this suite exists
# ---------------------
# #3032 taught the single-skill path to exit 2 for "could not measure", so an
# infrastructure outage never reads as a skill regression. The `--changed`
# fan-out is its sibling and used to collapse every non-zero into 1:
#
#     if ! bash "$0" "$skill_name" "${PASSTHROUGH_ARGS[@]}"; then
#         overall_exit=1
#     fi
#
# `--changed` is the path CI runs. So a run where every generation died
# returned 1 instead of 2, skill-eval.yml's `rc -eq 2` INCONCLUSIVE guard never
# matched, and the check went red on an outage, reintroducing exactly the false
# signal exit 2 exists to prevent.
#
# Real instance: run 30328867969 on fix/quickviz-visual-style-path. quickviz,
# 7/7 prompts "NO ANSWER (dead generation)", harness printed Trigger /
# Quality / Overall all INCONCLUSIVE, job still concluded failure.

RED=$'\033[0;31m'; GREEN=$'\033[0;32m'; YELLOW=$'\033[1;33m'; NC=$'\033[0m'
PASS=0; FAIL=0
log_pass() { echo "  ${GREEN}✓${NC} $1"; PASS=$((PASS + 1)); }
log_fail() { echo "  ${RED}✗${NC} $1"; FAIL=$((FAIL + 1)); }
section() { echo; echo "${YELLOW}$1${NC}"; }

echo "=========================================="
echo "  --changed fan-out exit propagation"
echo "=========================================="

if [[ ! -f "$RUNNER" ]]; then
    echo "${RED}FATAL: $RUNNER not found${NC}"
    exit 1
fi

# ---------------------------------------------------------------------------
section "1. The flattening form is gone from the fan-out"
# ---------------------------------------------------------------------------
if grep -q 'if ! bash "\$0" "\$skill_name"' "$RUNNER"; then
    log_fail "fan-out still uses 'if ! bash ...' — exit 2 collapses to 1"
else
    log_pass "fan-out no longer collapses every non-zero to 1"
fi

if grep -qE 'skill_exit -eq 2' "$RUNNER"; then
    log_pass "fan-out branches explicitly on the INCONCLUSIVE code"
else
    log_fail "fan-out does not special-case exit 2"
fi

# ---------------------------------------------------------------------------
section "2. The caller still honours the code the fan-out emits"
# ---------------------------------------------------------------------------
# Propagation is worthless unless skill-eval.yml maps 2 to a green, warned job.
if [[ -f "$WORKFLOW" ]] && grep -q 'rc" -eq 2' "$WORKFLOW"; then
    log_pass "skill-eval.yml maps rc=2 to a green, warned job"
else
    log_fail "skill-eval.yml no longer maps rc=2 — propagation would be pointless"
fi

# ---------------------------------------------------------------------------
section "3. Precedence: a real failure outranks an outage"
# ---------------------------------------------------------------------------
# Mirrors the shipped block. Test 1 keeps the two in lockstep: it fails the
# moment the runner reverts to the flattening form.
fanout_precedence() {
    local overall_exit=0 skill_exit
    for skill_exit in $1; do
        if [[ $skill_exit -eq 2 ]]; then
            if [[ $overall_exit -eq 0 ]]; then
                overall_exit=2
            fi
        elif [[ $skill_exit -ne 0 ]]; then
            overall_exit=1
        fi
    done
    echo "$overall_exit"
}

check() { # codes expected label
    local got
    got=$(fanout_precedence "$1")
    if [[ "$got" == "$2" ]]; then
        log_pass "$3  [$1] -> $got"
    else
        log_fail "$3  [$1] -> $got (want $2)"
    fi
}

check "0 0"   0 "all measured and passing stays 0"
check "2"     2 "a lone outage stays INCONCLUSIVE"
check "2 2"   2 "two outages stay INCONCLUSIVE"
check "0 2"   2 "pass plus outage is INCONCLUSIVE"
check "2 0"   2 "outage then pass is INCONCLUSIVE"
check "1"     1 "a real failure is a failure"
check "2 1"   1 "a real failure outranks an outage"
check "1 2"   1 "an outage cannot mask a real failure"
check "0 1 2" 1 "mixed resolves to failure"

echo
echo "=========================================="
echo "  Passed: ${GREEN}${PASS}${NC}  Failed: ${RED}${FAIL}${NC}"
echo "=========================================="
[ "$FAIL" -eq 0 ]
